// src/data/damodaran-country-risk.ts
var DAMODARAN_SOURCE_URL = damodaran_country_risk_default.source;
var DAMODARAN_UPDATED_AT = damodaran_country_risk_default.sourceUpdatedAt;
var DAMODARAN_COUNTRIES = damodaran_country_risk_default.countries;
var MATURE_MARKET_ERP = (() => {
  const unitedStates = DAMODARAN_COUNTRIES.find((entry) => entry.country === "United States");
  const premium = (unitedStates?.totalEquityRiskPremium ?? 0) - (unitedStates?.countryRiskPremium ?? 0);
  return premium > 0 ? premium / 100 : 0.0433;
})();

